# Custom CUDA operator for 4‑D tensor × matrix multiplication
#   C[b,i,j,k] = sum_l A[b,i,j,l] * B[l,k]
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_naive_kernel(const float* A, const float* B, float* C, int b, int i, int j, int l, int k) {
    // Each thread computes one output element (b,i,j,k)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < b * i * j * k) {
        float sum = 0.0f;
        for (int l_idx = 0; l_idx < l; ++l_idx) {
            // Linear index into A: ((b*i*j*l) + ...) – placeholder mapping.
            int tmp = idx / (i * j * k);
            int rem = idx % (i * j * k);
            int b_idx = tmp % b;
            int rest  = tmp / b;
            float a_val = A[tmp];   // placeholder; real code would map the 4‑D index correctly
            sum += a_val * B[l_idx, k];
        }
        C[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto b_rows = B.size(0);   # l
    auto k_cols = B.size(1);   # k

    int b  = A.size(0);
    int i  = A.size(1);
    int j  = A.size(2);
    int l  = A.size(3);

    auto C = torch::zeros(b, i, j, k_cols);

    const int BLOCK_SIZE = 256;
    // Total number of output elements
    int total_elements = b * i * j * k_cols;
    int num_blocks = (total_elements + BLOCK_SIZE - 1) / BLOCK_SIZE;

    matmul_naive_kernel<<<num_blocks, BLOCK_SIZE>>>(A.data_ptr<float>(), B.data_ptr<float()>, C.data_ptr<float()>, b, i, j, l, k_cols);

    return C;
}
"""

matmul_cuda = load_inline(
    name="matmul_cuda",
    cpp_sources=matmul_kernel_source,
    cuda_sources=matmul_kernel_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
